SparseMatrix::SparseMatrix(int m, int n)
{
    if (m <= 0 || n <= 0)
    {
        std::cout << "Dimensões inválidas para a matriz: " << m << " x " << n << std::endl;
        linhas = 0;
        colunas = 0;
        return;
    }

    linhas = m;
    colunas = n;
    vetorLinhas = new Node *[linhas]; // Correção: Aloque um vetor de ponteiros
