// Função para gerar uma chave de acesso aleatória
function generateAccessKey() {
return [...Array(50)].map(() => Math.random().toString(36)[2]).join('');
}

// Função para hash da chave de acesso
async function hashAccessKey(accessKey) {
const encoder = new TextEncoder();
const data = encoder.encode(accessKey);
const hashBuffer = await crypto.subtle.digest('SHA-256', data);
const hashArray = Array.from(new Uint8Array(hashBuffer));
return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

// Função para redirecionar (melhora a organização)
function redirectTo(url) {
window.location.href = url;
}

async function handleRegister() {
const username = document.getElementById('newUsername').value;
const password = document.getElementById('newPassword').value;
const accessKey = generateAccessKey();

try {
const hashedAccessKey = await hashAccessKey(accessKey);
const response = await fetch('register.php', {
method: 'POST',
headers: { 'Content-Type': 'application/json' },
body: JSON.stringify({ username, password, accessKey }),
});


const result = await response.json();

if (result.success) {
  localStorage.setItem('hashedAccessKey', hashedAccessKey);
  alert('Conta criada e chave de acesso gerada com sucesso!');
  showLoginForm(); 
} else {
  alert(result.message);
}
} catch (error) {
alert("Erro ao registrar: " + error.message);
}
}

async function handleLogin() {
const username = document.getElementById('username').value;
const password = document.getElementById('password').value;
const storedHashedAccessKey = localStorage.getItem('hashedAccessKey');

if (!storedHashedAccessKey) {
alert('Chave de acesso não encontrada. Iniciando processo de ativação.');
showActivationScreen();
return;
}

try {
const response = await fetch('login.php', {
method: 'POST',
headers: { 'Content-Type': 'application/json' },
body: JSON.stringify({ username, password, hashedAccessKey: storedHashedAccessKey }),
});


const result = await response.json();
console.log('Resposta do servidor:', result); // Adiciona log para ver a resposta do servidor

if (result.success) {
  alert('Login realizado com sucesso!');
  redirectTo('index.php');
} else if (result.message === 'Chave de acesso incorreta. Digite o código fixo.') {
  // Armazena as credenciais temporariamente para uso na ativação
  sessionStorage.setItem('tempUsername', username);
  sessionStorage.setItem('tempPassword', password);
  console.log('Credenciais armazenadas:', { username, password }); // Confirma o armazenamento
  showActivationScreen();
} else {
  alert(result.message);
}
} catch (error) {
alert("Erro ao fazer login: " + error);
}
}

function showActivationScreen() {
document.getElementById('loginForm').classList.add('hidden');
document.getElementById('registerForm').classList.add('hidden');
document.getElementById('activationScreen').classList.remove('hidden');
}

function showLoginForm() {
document.getElementById('activationScreen').classList.add('hidden');
document.getElementById('registerForm').classList.add('hidden');
document.getElementById('loginForm').classList.remove('hidden');

// Limpa os campos do formulário de login
document.getElementById('username').value = '';
document.getElementById('password').value = '';
}

async function handleActivation() {
const username = sessionStorage.getItem('tempUsername');
const password = sessionStorage.getItem('tempPassword');
console.log('Tentando recuperar credenciais:', { username, password }); // Verifica se as credenciais foram recuperadas
const activationCode = document.getElementById('activationCode').value;

if (!username || !password) {
alert('Erro: Informações de login não encontradas. Por favor, faça login novamente.');
showLoginForm();
return;
}

try {
const response = await fetch('regenerate_key.php', {
method: 'POST',
headers: { 'Content-Type': 'application/json' },
body: JSON.stringify({ username, password, activationCode }),
});


const result = await response.json();

if (result.success) {
  localStorage.setItem('hashedAccessKey', result.newHashedAccessKey);
  sessionStorage.removeItem('tempUsername');
  sessionStorage.removeItem('tempPassword');
  alert('Conta ativada com sucesso!');
  redirectTo('index.php');
} else {
  alert(result.message);
}
} catch (error) {
alert('Erro na ativação: ' + error.message);
}
}

